import{_ as s,a0 as i,w as u,s as d,I as n,x as l,a1 as p,A as e,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Recoll:Unix和Linux桌面的文本搜索工具 | LCTT x X-CMD","titleTemplate":false,"description":"Recoll:Unix和Linux桌面的文本搜索工具 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Recoll:Unix和Linux桌面的文本搜索工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Recoll:Unix和Linux桌面的文本搜索工具 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Recoll--Text Search Tool For Unix And Linux Desktops","title":"Recoll:Unix和Linux桌面的文本搜索工具","tag":"201312","desc":""},"relativePath":"201312/Recoll--Text Search Tool For Unix And Linux Desktops.md","filePath":"[post].md"}'),g={name:"201312/Recoll--Text Search Tool For Unix And Linux Desktops.md"};function a(x,t,m,T,R,f){const o=i("Link");return u(),d("div",null,[t[22]||(t[22]=n("h1",{id:"recoll-unix和linux桌面的文本搜索工具",tabindex:"-1"},[l("Recoll:Unix和Linux桌面的文本搜索工具 "),n("a",{class:"header-anchor",href:"#recoll-unix和linux桌面的文本搜索工具","aria-label":"Permalink to “Recoll:Unix和Linux桌面的文本搜索工具”"},"​")],-1)),n("p",null,[p(o,{href:"http://www.recoll.org/"},{default:e(()=>[...t[0]||(t[0]=[l("Recoll",-1)])]),_:1}),t[1]||(t[1]=l("是一個Unix和Linux桌面的文本搜索工具。Recoll可以搜索文件名和文件內的關鍵字。",-1))]),t[23]||(t[23]=r(`<p>Recoll可以為你做到以下這些。</p><ul><li>它可以搜索任何格式的文件</li><li>支持通配符</li><li>可以依據文件的作者、類型、大小和格式等條件進行搜索</li><li>可以搜索存儲在任何位置的文件，例如文件、歸檔文件、郵件附件等</li><li>支持桌面和網站集成</li><li>具備火狐插件，可索引web頁的歷史</li><li>點擊一下搜索結果就可以在本地編輯器內打開或者顯示文本預覽</li><li>它是免費的開源的，在GPL許可下發布</li></ul><p>###在Ubuntu/Linux Mint上安裝Recoll</p><p>Recoll在Ubuntu倉庫裏可以找到。然而，最好添加Recoll的倉庫以便安裝最新版本。</p><p>使用以下命令添加Recoll倉庫：</p><pre><code>sudo add-apt-repository
</code></pre><p>使用命令更新軟件列表：</p><pre><code>sudo apt-get update
</code></pre><p>現在就可以使用下面的命令安裝Recoll。</p><pre><code>sudo apt-get install recoll
</code></pre>`,10)),n("p",null,[t[3]||(t[3]=l("對於其它的發行版，可以去",-1)),p(o,{href:"http://www.lesbonscomptes.com/recoll/download.html"},{default:e(()=>[...t[2]||(t[2]=[l("下載頁面",-1)])]),_:1}),t[4]||(t[4]=l("下載源代碼並編譯安裝。",-1))]),t[24]||(t[24]=r(`<p>###啓動Recoll</p><p>Recoll可以從Dash或者菜單中啓動。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Menu_0014.jpg" alt=""></p><p>第一次啓動時，你需要索引整個home目錄。依據你 home 目錄裏儲存的東西的多少,需要的時間不等。按下<strong>Start indexing now</strong>按鈕開始索引。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Recoll_002.jpg" alt=""></p><p>假如你想更多的自定義索引，可以調整索引配置和索引計劃。要做到這一點，只需要點擊一下<strong>Indexing configuration</strong>或者<strong>Indexing schedule</strong>鏈接。假如你要稍後再去配置，你可以在Preferences(首選項)菜單裏配置這些選項。</p><p>一旦索引完成，你就可以搜索文件/文件夾了。結果將根據相關性展現，並顯示匹配的一小部分內容。</p><p>###配置</p><p>正如上面提到的，假如你想更多的控制索引的細節，你可以調節Recoll的索引功能。 在Recoll的工具中有兩個配置項</p><ol><li>索引配置</li><li>索引計劃</li></ol><p>讓我們來看一下上面這兩個的簡短描述。</p><p><strong>索引配置</strong>可以讓你索引時決定包含哪些目錄以及排除哪些目錄。默認情況下索引時將包含整個home目錄。你可以在這兒從索引中添加或移除目錄。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/home-sk-.recoll-_003.jpg" alt=""></p><p>你也可以定義web歷史隊列以及儲存web頁面的最大容量。</p><p><strong>index schedule</strong>則是可以讓制定一個計劃以便於進行自動索引或者當你登陸系統後就進行實時索引。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Index-scheduling-setup_004.jpg" alt=""></p><p>Recoll支持兩種索引計劃：</p><p><strong>Cron任務</strong> - 決定什麼時候開始運行以及寫入Crontab鍵值。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Cron-Dialog_006.jpg" alt=""></p><p>以上這個屏幕截圖中，Recoll的cron任務會在每天上午12點的時候執行。設置完cron任務後，點擊enable鍵激活它就可以咯。</p><p><strong>啓動時實時索引</strong> - 決定是否當你登陸入系統時進行實時索引。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Real-time-indexing-automatic-start_007.jpg" alt=""></p><p>激活這一選項，recoll的守護程序都會隨系統啓動。要注意的是這一選項只有在默認索引設置的情況下才可用。</p><p>###基本搜索</p><p>現在你已經對Recoll瞭解的足夠多了。是時候去搜索一下文件或者文件夾了。這個應用的美妙之處就在於它既可以搜索文件名還可以搜索文件內的關鍵詞。</p><p>在Recoll的用户界面中，在頂部右邊的搜索欄中鍵入要搜索的關鍵字，然後點擊Search按鈕。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Recoll_008.jpg" alt=""></p><p>如你在上圖所見，精確相關的內容將會顯示還能預覽到一小部分內容。你可以點擊Open按鈕直接打開搜索到的文件，或者在打開它之前使用預覽按鈕預覽它。</p><p>你還可以過濾搜索結果，使用分類例如媒體、消息、其它、演示文檔、電子表格或者文本等。更重要的是，你還可以選擇匹配任一項、全部項、文件名或者語言等的搜索結果。</p><p>###高級搜索</p><p>點擊菜單欄中的高級搜索圖標或者前往<strong>Tools-&gt;Advanced Search</strong>。這將打開一個新的對話窗口。在這兒你可以附加更多的限制條件來進行搜索。例如我可以搜索文件內容裏含有關鍵字“hp”以及文件名含有“storage”的文件。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Recoll_008.jpg" alt=""></p><p>這將找到並顯示文件內含有關鍵字“hp”且文件名含有“storage”的文件。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2013/11/Recoll_012.jpg" alt=""></p><p>###Unity桌面以及網站集成</p><p>這個應用支持桌面集成以及網站集成。假如你要把它集成到你的Ubuntu的Unity桌面中去，你可以用下面的命令安裝<strong>recoll-lens</strong>。</p><pre><code>sudo apt-get install recoll-lens
</code></pre><p>請注意，lens限制顯示結果最多顯示20條。假如你要顯示更多數目的搜索結果，編輯<strong>rclsearch.py</strong>，修改“<strong>if actual_results &gt;= 20:</strong>”這一行就可以咯。</p>`,38)),n("p",null,[t[6]||(t[6]=l("假如你使用火狐瀏覽器，要去搜索你每天訪問的瀏覽歷史，你可以使用這個",-1)),p(o,{href:"http://sourceforge.net/projects/recollfirefox/"},{default:e(()=>[...t[5]||(t[5]=[l("火狐擴展",-1)])]),_:1}),t[7]||(t[7]=l("。這個火狐擴展可以和Recoll一起工作去索引你全天瀏覽的網站。在安裝完這個擴展之後，在Recoll的索引配置中從web歷史標籤頁中激活它就可以咯。",-1))]),t[25]||(t[25]=n("p",null,[n("img",{src:"http://180016988.r.cdn77.net/wp-content/uploads/2013/11/home-sk-.recoll-_013.jpg",alt:""})],-1)),t[26]||(t[26]=n("p",null,"所有的Linux都在他們的文件管理器中內建了搜索功能，以便於儘可能容易的搜索文件/文件夾。對於那些不滿足於內置搜索功能並想尋找更高級文本搜索工具的人來説，Recoll是個值得一試的工具。我認為，這真是個容易使用且功能強大的工具，對基本搜索如此，對高級搜索也是如此.",-1)),t[27]||(t[27]=n("p",null,"歡呼吧！",-1)),n("p",null,[t[9]||(t[9]=l("如有問題，請參考我們的Q/A論壇 : ",-1)),p(o,{href:"http://ask.unixmen.com/"},{default:e(()=>[...t[8]||(t[8]=[l("http://ask.unixmen.com/",-1)])]),_:1}),t[10]||(t[10]=l(" 。",-1))]),t[28]||(t[28]=n("hr",null,null,-1)),n("p",null,[t[12]||(t[12]=l("via: ",-1)),p(o,{href:"http://www.unixmen.com/recoll-text-searching-tool-linux-desktops/"},{default:e(()=>[...t[11]||(t[11]=[l("http://www.unixmen.com/recoll-text-searching-tool-linux-desktops/",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=l("譯者：",-1)),p(o,{href:"https://github.com/Linux-pdz"},{default:e(()=>[...t[13]||(t[13]=[l("Linux-pdz",-1)])]),_:1}),t[16]||(t[16]=l(" 校對：",-1)),p(o,{href:"https://github.com/jasminepeng"},{default:e(()=>[...t[14]||(t[14]=[l("jasminepeng",-1)])]),_:1})]),n("p",null,[t[19]||(t[19]=l("本文由 ",-1)),p(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[17]||(t[17]=[l("LCTT",-1)])]),_:1}),t[20]||(t[20]=l(" 原創翻譯，",-1)),p(o,{href:"http://linux.cn/"},{default:e(()=>[...t[18]||(t[18]=[l("Linux中國",-1)])]),_:1}),t[21]||(t[21]=l(" 榮譽推出",-1))])])}const C=s(g,[["render",a]]);export{L as __pageData,C as default};
